# The Crossroads Market: by minecart, where the valley road meets the highway. Three traders' tents, open at the
# weekend (areas.c): seeds for any season, feed by the cartload, and Highland stock you can't buy in town.
map MARKET set=TOWN w=16 h=12 music=TOWN
key # FOREST block
key . GRASS walk
key c COBBLE walk
key * WILDFLOWER walk
key L LAMP block
key y HAY_BALE block
key x MINE_CRATE block
grid
